        long b = createProduct("B", 2000, 5);
        long orderId = createOrderId(a, 3, b, 5);
        assertThat(stockOf(a)).isEqualTo(7);
        assertThat(stockOf(b)).isZero();

        ResponseEntity<String> response = post("/api/orders/" + orderId + "/cancel");

